function navigate(u,dx,dy,dt,speed){if(u.team==='human'&&u.type==='robot'&&u.cannon===undefined)speed*=window.TriumphBalance.groundRobotMovementMultiplier;if(u.team==='human')for(const d of s.doors||[])if(!d.open&&!d.locked&&!d.destroyed&&dist(u,{x:d.cx,y:d.cy})<45){d.open=true;d.lastUse=s.t;sound(37,.2);}const goal={x:u.x+dx,y:u.y+dy};if(window.TriumphNavigation){const revision=navigationRevision();const next=window.TriumphNavigation.step(u,goal,window.TriumphDesertRiders.isRider(u)?window.TriumphDesertRiders.footprint(riderRouteBlocked,window.TriumphDesertRiders.radius(u)):u.team==='human'?humanRouteBlocked:blocked,revision);if(next){move(u,next.x-u.x,next.y-u.y,dt,speed);return;}}const angle=Math.atan2(dy,dx),step=Math.max(12,speed*dt);for(const offset of [0,.4,-.4,.85,-.85,1.4,-1.4,2,-2]){const a=angle+offset;if(!blocked(u.x+Math.cos(a)*step,u.y+Math.sin(a)*step)){move(u,Math.cos(a),Math.sin(a),dt,speed);return;}}}
