function cardinal(angle){return Math.round(angle/(Math.PI/2))*(Math.PI/2);}
function visible(a,b){
 if(b.type==='desert-worm'&&!window.TriumphDesertWorm.exposed(b))return false;
 // Weapon sight tests the projectile centerline to the target's hittable edge.
 // Walking clearance includes body padding and excludes boundary rows, which
 // incorrectly hid nests at y=752 and enemies standing beside solid terrain.
 if(b.hp!==undefined||b.team){const length=dist(a,b),radius=s.nests?.includes(b)?26:b.type==='queen'||b.type==='tank'?17:b===s.crystal?14:8,travel=Math.max(0,length-radius+1),steps=Math.ceil(travel/4);for(let i=1;i<=steps;i++){const f=travel/length*i/steps;if(blocked(a.x+(b.x-a.x)*f,a.y+(b.y-a.y)*f))return false;}return true;}
 return window.TriumphNavigation?window.TriumphNavigation.line(a,b,blocked):!blocked((a.x+b.x)/2,(a.y+b.y)/2);
}
