function spawnGroundBug(x,y){({x,y}=bugArrival(x,y));const special=rnd()<specialistRules.redbug.spawnChance,u=unit(x,y,'alien',special?'redbug':'soldier');u.hp=special?specialistRules.redbug.hp:s.difficulty?.bug||4;s.aliens.push(u);return u;}
function kill(u,owner){if(!u.alive||(u.type==='desert-worm'&&!window.TriumphDesertWorm.exposed(u)))return;cancelSupply(u);u.alive=false;sound(u.team==='alien'?(u.type==='queen'?20:5):6,.22);burst(u.x,u.y,10,u.team==='alien'?'#b57068':'#7d3f35');if(u.team==='alien'){s.kills++;if(s.waveKills)s.waveKills[u.type==='queen'?'queen':'normal']++;if(owner)s.score[owner-1]+=10;if(u.type==='queen')for(let i=0;i<4;i++){spawnGroundBug(u.x+rnd()*30-15,u.y+rnd()*30-15);}}if(u.type==='commander'){u.respawn=10;if(u.id===activeCommander)drag=null;}}
