function destroyProp(p){if(p.destroyed)return;p.destroyed=true;burst(p.x,p.y,p.wall?20:65);sound(p.wall?41:25,.5);if(!p.wall){s.fires.push({x:p.x,y:p.y,until:s.t+4,object:274});for(const a of s.aliens)if(a.alive&&dist(a,p)<65)damage(a,8,0);for(const n of s.nests)if(n.hp>0&&dist(n,p)<75)n.hp-=12;for(const q of s.props)if(q!==p&&q.hp>0&&dist(q,p)<60){q.hp=0;destroyProp(q);}}}
