function giveOrder(u,choice=null){u.order=choice===null?(u.order+1)%4:choice;u.selecting=false;for(const a of s.humans)if(a.alive&&a.type!=='commander'&&dist(a,u)<300){cancelSupply(a);a.useOrder=null;a.focusTarget=null;trackBurst(a,null);a.attackMove=null;a.order=u.order;a.leader=u.id;a.anchor={x:a.x,y:a.y};}sound([2,4,1,3][u.order],.55);if(!window.ORIGINAL_AUDIO)tone(440,.06,.025);}

function randomDirection(object){const mask=original.objects[object]?.movement?.direction>>>0,dirs=[];for(let i=0;i<32;i++)if(mask&(1<<i))dirs.push(i);return -(dirs[Math.floor(rnd()*dirs.length)]||0)*Math.PI/16;}
function supportPosition(create){const helper=s.supportHelpers[create.parent];const pad=s.telepads[Math.floor(rnd()*s.telepads.length)];return {x:(helper?.x??pad?.x??W/2)+create.x,y:(helper?.y??pad?.y??H/2)+create.y};}
function groundArrival(x,y){const desired={x:Math.max(12,Math.min(W-12,x)),y:Math.max(42,Math.min(H-16,y))},origin=s.humans.find(u=>u.type==='commander'&&u.alive)||desired;return window.TriumphNavigation?.destination(origin,desired,blocked)||desired;}
function flightEntersMap(pos,angle){const dx=Math.cos(angle),dy=Math.sin(angle);let enter=0,leave=Infinity;for(const [value,velocity,low,high] of [[pos.x,dx,12,W-12],[pos.y,dy,42,H-16]]){if(Math.abs(velocity)<1e-9){if(value<low||value>high)return false;continue;}const a=(low-value)/velocity,b=(high-value)/velocity;enter=Math.max(enter,Math.min(a,b));leave=Math.min(leave,Math.max(a,b));}return leave>=enter;}
function addTroop(object,x,y,type='soldier',rallyEligible=false){const u=unit(x,y,'human',type);u.object=object;u.grenades=0;Object.assign(u,groundArrival(x,y));s.humans.push(u);if(rallyEligible)assignRally(u);return u;}
function reinforcementStatus(type){const item={troops:'Ground Reinforcements',air:'Airial Reinforcements',tank:'Ground Support',blitz:'BLITZ!'}[type],rule=window.TriumphSupport.choose(s.support,item);if(!rule)return {rule:null,reason:'SUPPORT UNAVAILABLE'};const troops=s.humans.filter(u=>u.alive&&infantryType(u)).length;return rule.creates.some(c=>c.name==='Troop')&&troops>=s.rules.maxAliens?{rule:null,reason:'TROOPS FULL · WAIT FOR SPACE'}:{rule,reason:null};}
