function reinforce(type){const rule=reinforcementRule(type);if(!rule)return false;for(const sample of rule.sounds)sound(sample,.55);
for(const create of rule.creates){const pos=supportPosition(create);if(create.name==='Troop'){addTroop(create.object,pos.x,pos.y,type==='air'?'commando':'soldier',['troops','tank','blitz'].includes(type));continue;}if(create.name==='Tank'||create.name==='ground bot'){const u=unit(pos.x,pos.y,'human',create.name==='Tank'?'tank':'robot');u.object=create.object;u.hp=create.name==='ground bot'?7:8;Object.assign(u,groundArrival(pos.x,pos.y));s.humans.push(u);if(['troops','tank','blitz'].includes(type))assignRally(u);if(create.name==='ground bot')sound(49,.45);continue;}if(create.name==='player SPAWN shield'){burst(pos.x,pos.y,24,'#86ccff');continue;}
const kind=create.name==='Troop Carrier'?'carrier':create.name==='Air Support'?'air':create.name==='zipline creator'?'infiltration':null;if(kind){const r={...pos,object:create.object,kind,rallyEligible:['troops','tank','blitz'].includes(type),age:0,nextDrop:Math.ceil(s.t+1e-6),fireCool:0,grenadeCool:0,angle:randomDirection(create.object),path:window.TriumphSupport.path(create.object,pos.x,pos.y),entered:false};if(kind==='air'&&!flightEntersMap(r,r.angle))r.angle=Math.atan2(H/2-r.y,W/2-r.x);s.reinforcements.push(r);if(kind==='carrier')sound(18,.4);}}
return true;}
