function supportExplosion(x,y,owner=0){burst(x,y,45);sound(23,.35);for(const a of s.aliens)if(a.alive&&dist(a,{x,y})<65)damage(a,12,owner);for(const n of s.nests)if(n.hp>0&&dist(n,{x,y})<70)n.hp-=2;}
function moveHelper(h,dt){if(h.path){window.TriumphSupport.advance(h.path,dt);Object.assign(h,{x:h.path.x,y:h.path.y,angle:h.path.angle});return;}const speed=original.objects[h.object]?.movement?.ball?.speed;if(!speed)return;let x=h.x+Math.cos(h.angle)*speed*6.25*dt,y=h.y+Math.sin(h.angle)*speed*6.25*dt;if(x<0||x>W){h.angle=Math.PI-h.angle;x=Math.max(0,Math.min(W,x));}if(y<38||y>H-12){h.angle=-h.angle;y=Math.max(38,Math.min(H-12,y));}h.x=x;h.y=y;}
function updateSupport(dt){
 if(s.customAirPending&&s.t>=s.customMission.scheduledAir.at){s.customAirPending=false;for(const [i,[x,y]] of s.customMission.scheduledAir.points.entries())s.reinforcements.push({x,y:-24-i*64,object:176,kind:'air',age:0,nextDrop:Infinity,fireCool:0,grenadeCool:0,angle:Math.PI/2,entered:false,scheduledTarget:{x,y}});sound(21,.55);}
for(const h of Object.values(s.supportHelpers))moveHelper(h,dt);s.padClock-=dt;if(s.telepads.length&&s.originalMap.index>=17&&s.padClock<=0){s.padClock=.05;const pad=s.telepads[Math.floor(rnd()*s.telepads.length)],spawner=Object.values(s.supportHelpers).find(h=>h.name==='Ground spawner');if(spawner){spawner.x=pad.x+16;spawner.y=pad.y+16;}}
const countTroops=()=>s.humans.filter(u=>u.alive&&infantryType(u)).length;
for(const r of s.reinforcements){r.age+=dt;r.fireCool-=dt;r.grenadeCool-=dt;if(r.kind==='carrier'){window.TriumphSupport.advance(r.path,dt);if(r.path?.pause>0&&!r.unloadStarted){r.unloadStarted=true;r.path.pause=Math.max(r.path.pause,5);r.nextDrop=s.t;}if(!r.path){r.finished=true;continue;}r.x=r.path.x;r.y=r.path.y;r.angle=r.path.angle;if(r.path.pause>0&&s.t>=r.nextDrop&&countTroops()<s.rules.maxAliens){addTroop(52,r.x,r.y,'soldier',r.rallyEligible);r.nextDrop=s.t+1;}if(r.path.pause<=0&&!r.path.done)for(const a of s.aliens)if(a.alive&&dist(a,r)<30){kill(a,0);}if(r.path.done)r.finished=true;}
else if(r.kind==='air'){const speed=original.objects[r.object].movement.ball.speed*6.25;r.x+=Math.cos(r.angle)*speed*dt;r.y+=Math.sin(r.angle)*speed*dt;if(r.scheduledTarget&&!r.scheduledDropped&&r.y>=r.scheduledTarget.y)r.y=r.scheduledTarget.y;const inside=r.x>=0&&r.x<W&&r.y>=36&&r.y<H;if(inside&&!r.entered){r.entered=true;sound(22,.4);}if(inside){if(r.scheduledTarget&&!r.scheduledDropped&&r.y>=r.scheduledTarget.y&&countTroops()+s.drops.filter(d=>!d.finished).length<s.rules.maxAliens){supportDrop({...r,...r.scheduledTarget},'air');r.scheduledDropped=true;}if(s.t>=r.nextDrop&&countTroops()<s.rules.maxAliens&&!staticBlocked(r.x,r.y)){supportDrop(r,'air');r.nextDrop=Math.floor(s.t)+1;}if(r.fireCool<=0){r.fireCool=.330;fire({...r,id:0,type:'air',team:'human',weapon:0,cool:0,order:0});}if(r.grenadeCool<=0){r.grenadeCool=1;supportExplosion(r.x,r.y);}}if(r.entered&&!inside||r.age>20&&!r.scheduledTarget)r.finished=true;}
else {moveHelper(r,dt);if(s.t>=r.nextDrop&&countTroops()<s.rules.maxAliens){supportDrop(r,'zipline');r.nextDrop=Math.floor(s.t)+1;}if(r.age>=10)r.finished=true;}}
s.reinforcements=s.reinforcements.filter(r=>!r.finished);
for(const d of s.drops){d.age+=dt;if(d.zipline&&!d.thrown&&d.age>=d.duration/2){d.thrown=true;supportExplosion(d.x,d.y);}if(d.age>=d.duration){addTroop(52,d.x,d.y,'commando');d.finished=true;}}
s.drops=s.drops.filter(d=>!d.finished);}
function spawnPickupRoll(roll){if(s.customMission&&!s.customMission.randomPickups)return;const rules=window.ORIGINAL_PICKUPS?.[s.originalMap?.index];if(!rules)return;const troops=s.humans.filter(u=>u.alive&&infantryType(u)).length,compare=window.TriumphSupport.compare;for(const rule of rules.cases){if(rule.type==='growplant'&&(document.querySelector('#difficulty').value!=='normal'||!(rule.globals||[]).every(g=>compare(s.support.globals[g.index]||0,g.comparison,g.value))))continue;if(s.t<rule.minimumTime||!rule.checks.every(c=>compare(c.variable===0?roll:rules.secondary,c.comparison,c.difficulty?s.difficulty[c.difficulty]:c.value)))continue;if(rule.count&&!compare((rule.type==='growplant'?s.flowers.filter(f=>f.alive):s.pickups.filter(p=>p.type===rule.type)).length,rule.count.comparison,rule.count.value))continue;if(rule.troops){const tokens=rule.troops.tokens,limit=tokens.length===1?tokens[0].value:s.rules.maxAliens*tokens.at(-1).value;if(!compare(troops,rule.troops.comparison,limit))continue;}if(['troops','air','tank','blitz'].includes(rule.type)&&!reinforcementRule(rule.type))continue;const helper=s.supportHelpers[rule.parent];let point=helper?{x:helper.x+rule.x,y:helper.y+rule.y}:null;const clear=p=>p&&p.x>20&&p.x<W-20&&p.y>45&&p.y<H-20&&!blocked(p.x,p.y)&&!blocked(p.x-8,p.y-8)&&!blocked(p.x+8,p.y+8);if(!clear(point)){point=null;for(let attempt=0;attempt<64;attempt++){const p={x:24+rnd()*(W-48),y:48+rnd()*(H-72)};if(clear(p)){point=p;break;}}}if(point){if(rule.type==='growplant')s.flowers.push({...point,alive:true,object:rule.object});else s.pickups.push({...point,type:rule.type,object:rule.object});}}}
function updatePickupSpawns(dt){if(s.customMission&&!s.customMission.randomPickups)return;const rules=window.ORIGINAL_PICKUPS?.[s.originalMap?.index];if(!rules)return;s.pickupClock-=dt;while(s.pickupClock<=0){s.pickupClock+=rules.interval;spawnPickupRoll(Math.floor(rnd()*rules.range));}}
function hasRespawnSupport(){return s.humans.some(u=>u.alive&&u.type!=='commander')||s.reinforcements.some(r=>!r.finished&&['carrier','air','infiltration'].includes(r.kind))||s.drops.length>0;}
function respawnCommander(u){const origin=u.spawn||{x:90,y:260+u.id*35},p=window.TriumphNavigation?.destination(origin,origin,blocked)||origin;u.alive=true;u.hp=1;u.x=p.x;u.y=p.y;u.weapon=0;u.weaponTime=0;u.selecting=false;u.external=null;u.ai=null;u.patrol=null;u.cool=.25;u.shieldUntil=s.t+.6;u.respawn=0;burst(u.x,u.y,24,'#bbdd99');}
