function advance(){window.TriumphMusic?.unlock();if(s.mode==='briefing'){s.mode='playing';paused=true;drag=null;keys.clear();canvas.focus();tone(400,.15);}else if(s.customId&&(s.mode==='victory'||s.mode==='defeat'))restartMission();else if(s.mode==='victory')begin(s.level===8?0:s.level+1,s.level===8?0:s.merits);else if(s.mode==='defeat')begin(s.merits>=100?s.level:0,s.merits>=100?s.merits-100:0);else paused=!paused;}
document.querySelector('#rally').onclick=toggleRally;
for(let id=1;id<=4;id++)document.querySelector('#cmd-'+id).onclick=()=>selectCommander(id);for(let order=0;order<4;order++)document.querySelector('#order-'+order).onclick=()=>{const u=selectedCommander();if(u?.alive&&s.mode==='playing'){giveOrder(u,order);canvas.focus();updateCommandPanel();}};
window.addEventListener('keydown',e=>{window.TriumphMusic?.unlock();if(document.querySelector('#controls').open||document.querySelector('#unit-guide').open)return;if(presets.flat().includes(e.code)||['Space','Enter'].includes(e.code))e.preventDefault();const repeat=keys.has(e.code);keys.add(e.code);if(repeat||e.repeat)return;if(e.code==='KeyR'&&s.mode==='playing'){e.preventDefault();toggleRally();return;}if(e.code==='Escape'&&rallyMode){e.preventDefault();toggleRally();return;}if(e.code==='Space'||e.code==='Escape'){paused=!paused;drag=null;}if(e.code==='Enter')advance();if(e.code==='F2'){e.preventDefault();restartMission();}if(s.mode==='playing'&&mouseMode==='commander')for(let i=0;i<4;i++){if(i+1!==activeCommander)continue;const u=s.humans.find(a=>a.id===i+1);const binding=i+1===activeCommander?presets[0]:presets[i];if(i===0&&activeCommander!==1)continue;if(u.selecting&&binding.slice(0,4).includes(e.code)){giveOrder(u,[2,3,0,1][binding.indexOf(e.code)]);continue;}if(e.code===binding[4]&&u.alive&&!paused)interact(u);if(e.code===binding[5]){const u=s.humans.find(a=>a.id===i+1);if(!u.alive)continue;if(keys.has(binding[4])&&!paused){grenade(u);u.grenadeCool=s.t+.330;}else u.selecting=true;}}});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{drag=null;keys.clear();if(s.mode==='playing')paused=true;});
document.querySelector('#difficulty').onchange=()=>restartMission();
document.querySelector('#mission').onchange=e=>{const value=e.target.value;if(window.TriumphCustomMissions.get(value))loadCustomMission(value);else loadOriginal(Number(value));};
document.querySelector('#start').onclick=()=>{advance();canvas.focus();};document.querySelector('#pause').onclick=()=>{paused=!paused;drag=null;canvas.focus();};document.querySelector('#reset').onclick=()=>{restartMission();canvas.focus();};document.querySelector('#options').onclick=()=>{controlsWasPaused=paused;paused=true;drag=null;keys.clear();document.querySelector('#controls').showModal();};document.querySelector('#close').onclick=()=>{document.querySelector('#controls').close();paused=controlsWasPaused;canvas.focus();};
window.triumph={state:()=>JSON.parse(JSON.stringify({mission:s.customId?null:s.level+1,customId:s.customId||null,merits:s.merits,mode:s.mode,paused,time:s.t,activeCommander,mouseMode,rallyMode,rallyPoints,missionProgress:missionProgress(),selectedTroops:[...selection].filter(selectable).map(u=>({x:u.x,y:u.y,type:u.type,attackMove:u.attackMove,useOrder:u.useOrder?{kind:u.useOrder.kind,x:u.useOrder.x,y:u.useOrder.y}:null,focusTarget:u.focusTarget?{x:u.focusTarget.x,y:u.focusTarget.y,hp:u.focusTarget.hp}:null})),army:s.humans.filter(u=>u.alive&&u.type!=='commander').length,commanders:s.humans.filter(u=>u.type==='commander'),aliens:s.aliens,vents:s.vents,nests:s.nests,pickups:s.pickups,gate:s.gate,doors:s.doors,terminals:s.terminals,props:s.props,cannons:(s.cannons||[]).map(c=>({...c,occupant:c.occupant?{alive:c.occupant.alive}:null})),reinforcements:s.reinforcements.map(({path,...r})=>r),drops:s.drops,crystal:s.crystal,waveRemaining:s.waveRemaining,waveKills:s.waveKills})),loadMission:(level)=>{if(!Number.isInteger(level)||level<1||level>9)throw Error('Mission must be 1–9');loadOriginal(level-1);},loadCustomMission,customMissions:window.TriumphCustomMissions.list,command:(id,q)=>{if(![2,3].includes(id))throw Error('Assistant controls commanders 2 and 3');const u=s.humans.find(a=>a.id===id);u.external={...q,until:s.t+Math.min(3,Math.max(.05,q.seconds||.5))};if(q.order!==undefined)giveOrder(u,typeof q.order==='number'?q.order:null);if(q.grenade)grenade(u);},missions};
